/* ===================================================================
   Buyer Log — TR/EN arayüz sözlüğü (i18n-runtime.js tarafından kullanılır)
   Her kayıt [Türkçe, English] çiftidir. Çalışma zamanı katmanı EN kipinde
   Türkçe metni, TR kipinde İngilizce metni karşılığıyla değiştirir; {0},
   {1} … yer tutucuları dinamik değerleri temsil eder. "same" listesi iki
   dilde de bilinçli olarak aynı kalan terimlerdir (çevrilmez).
   Kaynak: modüllerdeki mevcut TR/EN çiftleri + eksik kalan metinlerin
   çevirileri. Yeni metin eklerken modülde TR/EN çiftini yazmak asıl
   yoldur; bu sözlük eksik/eski render kalıntılarına karşı güvenlik ağıdır.
   =================================================================== */
